 delete from mysql.roles_mapping where Role='test_role1';
 flush privileges;
 drop user 'test_user'@'localhost';
+
+#
+# MDEV-9898 SET ROLE NONE can crash mysqld.
+#
+
+create user user1;
+
+--connect (con1,localhost,user1,,)
+select current_user;
+show grants;
+set role none;
+
+connection default;
+drop user user1;
+

problem_statement:
SET ROLE NONE can crash mysqld

A user is granted one role only and no other privileges.
{{SET ROLE NONE}} makes mysqld crash
{noformat}
mysql> SET ROLE NONE;
ERROR 2013 (HY000): Lost connection to MySQL server during query
{noformat}
